package dev.prism;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.http.ResponseEntity;
import static org.junit.jupiter.api.Assertions.*;
import java.util.List;
import java.util.Map;

class GatewayTest {
  JdbcTemplate db; Gateway gateway;
  @BeforeEach void setup(){
    var source=new DriverManagerDataSource("jdbc:h2:mem:prism"+System.nanoTime()+";DB_CLOSE_DELAY=-1","sa","");
    db=new JdbcTemplate(source);
    db.execute("CREATE TABLE usage_record(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, api_key VARCHAR(100), model VARCHAR(160), provider VARCHAR(50), status INT, prompt_tokens INT, completion_tokens INT, cost DOUBLE, cache_hit BOOLEAN, fallback BOOLEAN, latency_ms BIGINT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
    db.execute("CREATE TABLE semantic_cache(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, api_key VARCHAR(100), normalized_prompt VARCHAR(4000), answer CLOB, model VARCHAR(100), prompt_tokens INT, completion_tokens INT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
    gateway=new Gateway(db);gateway.seed();
  }
  Gateway.ChatRequest request(String model,String content){return new Gateway.ChatRequest(model,List.of(Map.of("role","user","content",content)),false,100,null);}
  @Test void rejectsInvalidKey(){assertEquals(401,gateway.chat("Bearer wrong",request("fast","hi")).getStatusCode().value());}
  @Test void enforcesModelAllowlist(){var r=gateway.chat("Bearer prism-demo-student",request("smart","hi"));assertEquals(403,r.getStatusCode().value());}
  @Test void recordsUsageAndReturnsMeteringHeaders(){var r=gateway.chat("Bearer prism-demo-team",request("fast","Explain token metering"));assertEquals(200,r.getStatusCode().value());assertNotNull(r.getHeaders().getFirst("x-prism-provider"));assertNotNull(r.getHeaders().getFirst("x-prism-cost-usd"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM usage_record",Integer.class));}
  @Test void semanticCacheHitsParaphraseButIsScopedToKey(){gateway.chat("Bearer prism-demo-team",request("fast","Explain semantic caching simply"));var hit=gateway.chat("Bearer prism-demo-team",request("fast","Describe semantic cache in simple terms"));assertEquals("HIT",hit.getHeaders().getFirst("x-prism-cache"));var isolated=gateway.chat("Bearer prism-demo-student",request("fast","Describe semantic cache in simple terms"));assertEquals("MISS",isolated.getHeaders().getFirst("x-prism-cache"));}
  @Test void enforcesRateLimitAtTwentyPerMinute(){for(int i=0;i<20;i++)assertEquals(200,gateway.chat("Bearer prism-demo-student",request("fast","rpm test "+i)).getStatusCode().value());assertEquals(429,gateway.chat("Bearer prism-demo-student",request("fast","rpm overflow")).getStatusCode().value());}
  @Test void costUsesProviderUsageAndRouterHandlesTrapCases(){assertEquals(.000555,gateway.computeCost("mock-fast",100,900),1e-12);assertEquals("smart",gateway.classify("Prove this claim in eight words"));assertEquals("smart",gateway.classify("Find the bug in a short concurrent protocol"));assertEquals("fast",gateway.classify("hello ".repeat(40)));}
  @Test void dashboardProvidesAllRequestsPagedWithoutReturningVirtualKeySecrets(){gateway.chat("Bearer prism-demo-team",request("fast","dashboard audit one"));Map<String,Object> page=gateway.requestPage(0,10,"","","","",false);assertEquals(1,((Number)page.get("total")).intValue());@SuppressWarnings("unchecked") Map<String,Object> row=(Map<String,Object>)((List<?>)page.get("items")).get(0);assertEquals("demo-team",row.get("KEY_LABEL"));assertFalse(row.containsKey("API_KEY"));Map<String,Object> totals=gateway.summary();assertTrue(totals.containsKey("totals"));}
  @Test void openRouterUsageCostAndStreamChunksAreParsed(){OpenRouterProviderAdapter adapter=new OpenRouterProviderAdapter();var usage=adapter.parseStreamUsage("{\"id\":\"gen-1\",\"model\":\"vendor/model\",\"usage\":{\"prompt_tokens\":12,\"completion_tokens\":7,\"cost\":0.0042}}","fallback/model");assertEquals(.0042,usage.cost());assertEquals(12,usage.promptTokens());assertEquals("vendor/model",usage.model());assertEquals("hello",adapter.streamChunkContent("{\"choices\":[{\"delta\":{\"content\":\"hello\"}}]}"));assertEquals("upstream rejected",adapter.streamError("{\"error\":{\"message\":\"upstream rejected\"}}"));}
  @Test void mockProviderFailureFallsBackAndIsRecorded(){gateway.down("mock-fast",true);var response=gateway.chat("Bearer prism-demo-team",request("fast","force fallback path"));assertEquals(200,response.getStatusCode().value());assertEquals("true",response.getHeaders().getFirst("x-prism-fallback"));assertEquals("mock-smart",db.queryForObject("SELECT model FROM usage_record",String.class));}
}
